cd /var/tmp/loop-bench/runs/9d4c7bcbb32a/workspace/target; python3 - <<'E'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("""import AjvModule from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
""","""import {createRequire} from 'node:module';
""")
a=s.index("// ajv is CommonJS")
b=s.index("function describeError")
s=s[:a]+"""interface ErrorObject {
  keyword: string;
  instancePath: string;
  params: Record<string, unknown>;
}

interface ValidateFunction {
  (data: unknown): boolean;
  errors?: ErrorObject[] | null;
}

interface AjvInstance {
  compile(schema: Record<string, unknown>): ValidateFunction;
}

type AjvConstructor = new (options: Record<string, unknown>) => AjvInstance;

// ajv is CommonJS and carries its class as module.exports and .default; require it so ESM, vitest and tsc agree regardless of ajv's type shape.
const loaded = createRequire(import.meta.url)('ajv') as AjvConstructor & {default?: AjvConstructor};
const Ajv: AjvConstructor = loaded.default ?? loaded;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

"""+s[b:]
s=s.replace("const params = error.params as Record<string, unknown>;","const params = error.params;")
open(p,'w').write(s)
E
npx prettier --write src/orchestration/tools/registry.ts; timeout 300 npx vitest run src/orchestration/tools/registry.test.ts 2>&1 | grep -v '^\s*$' | grep -E 'Test|✓|✗|FAIL|passed|failed' | head

